package dev.jobflow.api; import dev.jobflow.api.JobDtos.*; import dev.jobflow.domain.*; import dev.jobflow.repo.JobRepository; import dev.jobflow.service.JobService; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final JobService jobs;private final JobRepository repo;public AdminController(JobService j,JobRepository r){jobs=j;repo=r;}@GetMapping("/jobs") Page<JobResponse> list(@RequestParam(required=false) JobStatus status,@PageableDefault(size=50) Pageable p){return jobs.listAdmin(status,p).map(JobResponse::of);}@GetMapping("/dead-letter-jobs") Page<JobResponse> dlq(@PageableDefault(size=50) Pageable p){return jobs.listAdmin(JobStatus.DEAD_LETTER,p).map(JobResponse::of);}@PostMapping("/dead-letter-jobs/{id}/replay") JobResponse replay(@PathVariable UUID id){return JobResponse.of(jobs.replay(id));}@GetMapping("/workers") Map<String,Long> workers(){return Map.of("processing",repo.countByStatus(JobStatus.PROCESSING),"queued",repo.countByStatus(JobStatus.QUEUED),"retryWaiting",repo.countByStatus(JobStatus.RETRY_WAIT));}}
